   ],
   "evidence": [
    "replica-1 was on gpu-1 which had new ECC errors",
    "only replica-1 failed canary questions while others were healthy",
    "no recent config changes specific to replica-1"
   ],
   "status": "fixed",
   "confidence": 1.0
