    "gateway",
    "workers",
    "replicas"
   ],
   "setting": null,
   "explains": [
    "errors:gateway",
    "slow:gateway",
    "slow:replica-4"
   ],
   "evidence": [
    "incoming traffic is 1.03x normal (not significantly overloaded)",
    "gateway error rate is 20.7% (abnormally high for slight overload)",
    "identity-service returned 503 connection refused",
    "gateway timeout_ms is 30000ms (high), causing slow p95 latency when waiting for identity-service",
    "replica-4 is slow likely due to queue backup or shared resource contention from gateway delays"
   ],
   "status": "suspected",
   "confidence": 0.8
  },
  {
   "id": "H3",
   "type": "external_dependency",
   "component": [
    "identity-service"
   ],
   "setting": null,
   "explains": [
    "errors:gateway",
    "slow:gateway"
   ],
   "evidence": [
    "ERROR gateway: 503 from identity-service: connection refused",
    "identity-service is owned by another team",
    "gateway logs show high latency due to waiting on identity-service"
   ],
   "status": "suspected",
   "confidence": 0.9
  }
 ],
 "actions": [
  {
   "action": "set_weight",
   "args": {
    "replica": "replica-4",
    "weight": 0
   },
   "hypothesis": "H2",
   "purpose": "mitigate",
   "why": "Replica-4 is showing high latency; isolating it helps determine if the slowness is node-specific or systemic. If other replicas are also slow due to gateway/identity issues, this prevents further load on a potentially struggling node."
  },
  {
   "action": "escalate",
   "args": {
    "team": "identity-team",
    "summary": "Identity-service is returning 503 Connection Refused, causing 20.7% error rate and high latency in gateway. Traffic is near normal (1.03x). Please investigate immediately."
   },
   "hypothesis": "H3",
   "purpose": "escalate",
   "why": "The root cause of gateway errors and latency is an external dependency failure (identity-service) which is not within my scope to fix directly."
  },
  {
   "action": "inspect",
   "args": {
    "what": "logs",
    "component": "gateway",
    "contains": "identity-service"
   },
   "hypothesis": "H3",
   "purpose": "investigate",
   "why": "To gather more details on the identity-service failures and confirm if they are widespread or intermittent."
  }
 ],
 "summary": "Escalated identity-service outage to the responsible team as it is the primary cause of gateway errors and latency; isolated replica-4 to prevent further impact while investigating."
}
